import type { Metadata } from 'next';
import ArticleCard, { Article } from '@/components/ArticleCard';
import { API_ROUTES } from '@/lib/api';
import styles from './page.module.css';

export const metadata: Metadata = {
  title: 'On This Day in the 90s | The Nineties Times',
  description:
    'A daily timeline of 1990s moments, pop culture, and nostalgia—generated by Gemini.',
  alternates: { canonical: '/on-this-day-in-the-90s' },
};

type PagedResult<T> = { items?: T[] };

async function searchWith(params: URLSearchParams): Promise<Article[]> {
  try {
    const res = await fetch(API_ROUTES.ARTICLE.SEARCH_PAGED(params.toString()), {
      cache: 'no-store',
    });
    if (!res.ok) return [];
    const data = (await res.json()) as PagedResult<Article>;
    return Array.isArray(data.items) ? data.items : [];
  } catch {
    return [];
  }
}

async function fetchOnThisDay(): Promise<Article[]> {
  const params = new URLSearchParams({
    page: '1',
    pageSize: '12',
    sort: 'date_desc',
    type: 'Article',
    category: 'Info',
    keyword: 'on-this-day-90s',
  });

  const primary = await searchWith(params);
  if (primary.length > 0) return primary;

  // Fallback: older entries may only include the shorter tag.
  const fallback = new URLSearchParams({
    page: '1',
    pageSize: '12',
    sort: 'date_desc',
    type: 'Article',
    category: 'Info',
    keyword: 'on-this-day',
  });
  return searchWith(fallback);
}

export default async function OnThisDayPage() {
  const articles = await fetchOnThisDay();

  return (
    <div className={styles.page}>
      <header className={styles.hero}>
        <span className={styles.kicker}>Daily timeline</span>
        <h1>On This Day in the 90s</h1>
        <p>A quick hit of 1990s moments to kick off your nostalgia.</p>
      </header>

      <section className={styles.grid}>
        {articles.length === 0 ? (
          <div className={styles.empty}>
            The timeline is warming up. Check back soon for today&apos;s drop.
          </div>
        ) : (
          articles.map((article) => <ArticleCard key={article.id} article={article} />)
        )}
      </section>
    </div>
  );
}

